"""genusleak Cayley-graph walks on Cl(-4kN) generated by small split prime forms.

OPERATIONAL part (sees only D): enumerate H = <S> by BFS on reduced forms, the step table, exact closed-walk
counts W_t, and the free-abelian closed-walk counts W_t^free.  Exponential in log N (|H| ~ sqrt N): a toy
measurement device, not an algorithm.

The hidden genus signal G_t needs p and lives in harness.py.
"""
from __future__ import annotations

from fractions import Fraction
from math import comb, factorial
from typing import Dict, List, Tuple

import numpy as np

from .forms import Form, compose, identity, inverse, prime_form, split_primes

__all__ = ["enumerate_subgroup", "closed_walks", "free_closed_walks", "girth_bound"]


def enumerate_subgroup(D: int, gens: List[Form]) -> Tuple[List[Form], Dict[Form, int], np.ndarray]:
    """BFS over H = <gens>.  Returns (elements, index, step table) with step[i, s] the index of
    elements[i] * steps[s], steps = gens + inverses (in that order)."""
    steps = list(gens) + [inverse(g) for g in gens]
    e = identity(D)
    elems: List[Form] = [e]
    idx: Dict[Form, int] = {e: 0}
    table: List[List[int]] = []
    i = 0
    while i < len(elems):
        row = []
        x = elems[i]
        for s in steps:
            y = compose(x, s)
            j = idx.get(y)
            if j is None:
                j = len(elems)
                idx[y] = j
                elems.append(y)
            row.append(j)
        table.append(row)
        i += 1
    return elems, idx, np.array(table, dtype=np.int64)


def closed_walks(table: np.ndarray, tmax: int) -> List[int]:
    """W_t for t = 0..tmax: number of closed walks of length t at the identity (exact integers)."""
    h, m = table.shape
    vec = np.zeros(h, dtype=object)
    vec[0] = 1
    out = [1]
    for _ in range(tmax):
        new = np.zeros(h, dtype=object)
        for s in range(m):
            # walks ending at y = x * step_s come from x; scatter-add
            np.add.at(new, table[:, s], vec)
        vec = new
        out.append(int(vec[0]))
    return out


def free_closed_walks(r: int, tmax: int) -> List[int]:
    """Closed walks of length t on Z^r with steps +-e_i (exact): t! [z^t] (sum_m C(2m, m) z^{2m}/(2m)!)^r."""
    one = [Fraction(0)] * (tmax + 1)
    for m in range(0, tmax + 1, 2):
        one[m] = Fraction(comb(m, m // 2), factorial(m))
    poly = [Fraction(0)] * (tmax + 1)
    poly[0] = Fraction(1)
    for _ in range(r):
        new = [Fraction(0)] * (tmax + 1)
        for i, a in enumerate(poly):
            if a == 0:
                continue
            for j in range(0, tmax + 1 - i):
                if one[j]:
                    new[i + j] += a * one[j]
        poly = new
    out = []
    for t in range(tmax + 1):
        v = poly[t] * factorial(t)
        assert v.denominator == 1
        out.append(int(v))
    return out


def girth_bound(N: int, k: int, ells: List[int]) -> int:
    """g0 = ceil(log(kN)/log(max ell)) (exact integer computation): every nonzero relation e in Z^S has
    sum |e_ell| >= g0 (Lemma GIRTH)."""
    M, L = k * N, max(ells)
    g, pw = 0, 1
    while pw < M:
        pw *= L
        g += 1
    return g


def setup(N: int, k: int = 1, nprimes: int = 6):
    D = -4 * k * N
    ells = split_primes(D, nprimes)
    gens = [prime_form(D, l) for l in ells]
    elems, idx, table = enumerate_subgroup(D, gens)
    return D, ells, gens, elems, idx, table
